RSpec.describe Timekeeping::Handoff::Reconciliation do
  # "Any difference that the pre-flight did not list aborts the handoff."
  # A correction names the check, the row and the field it explains, so a second change on that row stays unlisted.
  it "a correction listed for one field of an entry does not excuse a changed note on the same entry" do
    at = Time.utc(2026, 1, 5, 9)
    entry = lambda do |id, company_id, **overrides|
      {
        "id" => id, "company_id" => company_id, "version" => 1, "project_id" => 1, "user_id" => 1, "agent_id" => nil,
        "work_date" => Date.new(2026, 1, 5), "duration" => 60.0, "note" => "", "bill_status" => "unbilled",
        "review_status" => "not_required", "locked" => false, "source" => "manual", "source_metadata" => {},
        "external_run_id" => nil, "external_session_id" => nil, "proof_url" => nil, "proof_metadata" => {},
        "discarded_at" => nil, "created_at" => at, "updated_at" => at
      }.merge(overrides.transform_keys(&:to_s))
    end
    checkpoint_of = lambda do |entries|
      tables = Timekeeping::Handoff::Checkpoint::TABLES.keys.index_with { [] }
      Timekeeping::Handoff::Checkpoint.build(tables: tables.merge("entries" => entries))
    end
    projection_of = lambda do |row|
      row.merge(
        "bill_status" => TimesheetEntry.bill_statuses.fetch(row["bill_status"]),
        "review_status" => TimesheetEntry.review_statuses.fetch(row["review_status"])
      )
    end
    snapshots = { 101 => { company_id: 101, values: {} }.freeze }

    source_row = entry.call(1, 101, note: "original note")
    loaded_row = entry.call(1, 101, note: "copied wrong", locked: true)
    correction = described_class::Correction.new(check: :entries, row_key: [1], field: "locked")

    result = described_class.run(
      source: checkpoint_of.call([source_row]), checkpoint: checkpoint_of.call([loaded_row]),
      projection: [projection_of.call(loaded_row.merge("locked" => false))],
      source_intents: [], intents: [], next_entry_id: 100,
      money_before: snapshots, money_after: snapshots,
      listed_corrections: { 101 => [correction] }
    )

    report = result.companies.fetch(101)
    entry_differences = report.unlisted.select { |d| d.check == :entries }
    expect(entry_differences.map { |d| d.field.to_s }).to include("note")
    expect(entry_differences.map { |d| d.field.to_s }).not_to include("locked")
    expect(report).to be_abort
    expect(result).to be_abort
  end
end

