RSpec.describe Timekeeping::Handoff::Reconciliation do
  # "Emit every reconciliation difference and any financial snapshot change with `company_id`."
  # The money difference kept in the result must still reach FinancialSnapshotChanged, which reads kind and record_id.
  it "reporting a changed invoice discount emits the financial change event with its company and no money value" do
    empty = Timekeeping::Handoff::Checkpoint.build(tables: Timekeeping::Handoff::Checkpoint::TABLES.keys.index_with { [] })
    before = { 101 => { company_id: 101, values: { [:invoice, 5, :discount] => BigDecimal("10.00") } }.freeze }
    after = { 101 => { company_id: 101, values: { [:invoice, 5, :discount] => BigDecimal("98765.43") } }.freeze }

    result = described_class.run(
      source: empty, checkpoint: empty, projection: [], source_intents: [], intents: [],
      next_entry_id: 100, money_before: before, money_after: after
    )
    expect(result.companies.fetch(101)).to be_abort

    returned = nil
    event = assert_event_reported("Timekeeping::FinancialSnapshotChanged") do
      returned = described_class.report(result)
    end

    expect(returned).to eq(result)
    data = event[:payload].to_h[:data]
    expect(data[:company_id]).to eq(101)
    expect(data[:kind].to_s).to eq("invoice")
    expect(data[:record_id]).to eq(5)
    expect(data[:field].to_s).to eq("discount")
    expect(JSON.generate(event[:payload].to_h)).not_to include("98765")
  end
end

RSpec.describe Timekeeping::Handoff::Reconciliation do
  # "Equal; no `provisional` reservation remains; at most one committed reservation per entry."
  it "a committed reservation delivered twice for one entry aborts its company instead of collapsing into one" do
    at = Time.utc(2026, 1, 5)
    bill_name, bill_number = TimesheetEntry.bill_statuses.first
    review_name, review_number = TimesheetEntry.review_statuses.first
    entry = lambda do |company_id|
      {
        "id" => 7, "company_id" => company_id, "version" => 1, "project_id" => 1, "user_id" => 1, "agent_id" => nil,
        "work_date" => Date.new(2026, 1, 5), "duration" => 60.0, "note" => "work", "bill_status" => bill_name,
        "review_status" => review_name, "locked" => true, "source" => "manual", "source_metadata" => {},
        "external_run_id" => nil, "external_session_id" => nil, "proof_url" => nil, "proof_metadata" => {},
        "discarded_at" => nil, "created_at" => at, "updated_at" => at
      }
    end
    reservation = lambda do |company_id|
      { "company_id" => company_id, "entry_id" => 7, "invoice_id" => 9, "state" => "committed",
        "disposition" => "active", "operation_id" => nil, "created_at" => at }
        .reverse_merge(Timekeeping::Handoff::Checkpoint::TABLES.fetch("reservations").index_with { nil })
    end
    tables = lambda do |reservations|
      { "entries" => [entry.call(101), entry.call(202)], "reservations" => reservations,
        "invoice_operations" => [], "entry_audits" => [], "idempotency_records" => [],
        "service_idempotency_receipts" => [] }
    end
    source = Timekeeping::Handoff::Checkpoint.build(tables: tables.call([reservation.call(101), reservation.call(202)]))
    checkpoint = Timekeeping::Handoff::Checkpoint.build(
      tables: tables.call([reservation.call(101), reservation.call(101), reservation.call(202)])
    )
    projection = [101, 202].map do |company_id|
      entry.call(company_id).merge("bill_status" => bill_number, "review_status" => review_number)
    end
    money = [101, 202].index_with { |company_id| { company_id:, values: {} } }

    result = described_class.run(
      source:, checkpoint:, projection:, source_intents: [], intents: [], next_entry_id: 1000,
      money_before: money, money_after: money
    )

    expect(result.abort?).to be(true)
    expect(result.companies.fetch(101).abort?).to be(true)
    expect(result.companies.fetch(101).checks.fetch(:reservations)).not_to be_empty
    expect(result.companies.fetch(101).unlisted.map(&:company_id).uniq).to eq([101])
    expect(result.companies.fetch(202).abort?).to be(false)
    expect(result.companies.fetch(202).unlisted).to be_empty
  end
end

RSpec.describe Timekeeping::Handoff::Reconciliation do
  # "Emit every reconciliation difference and any financial snapshot change with `company_id`."
  it "reporting differences in two companies stores one difference event per difference under its own company" do
    at = Time.utc(2026, 1, 5)
    bill_name, bill_number = TimesheetEntry.bill_statuses.first
    review_name, review_number = TimesheetEntry.review_statuses.first
    entry = lambda do |company_id, note|
      {
        "id" => 7, "company_id" => company_id, "version" => 1, "project_id" => 1, "user_id" => 1, "agent_id" => nil,
        "work_date" => Date.new(2026, 1, 5), "duration" => 60.0, "note" => note, "bill_status" => bill_name,
        "review_status" => review_name, "locked" => false, "source" => "manual", "source_metadata" => {},
        "external_run_id" => nil, "external_session_id" => nil, "proof_url" => nil, "proof_metadata" => {},
        "discarded_at" => nil, "created_at" => at, "updated_at" => at
      }
    end
    tables = lambda do |entries|
      { "entries" => entries, "reservations" => [], "invoice_operations" => [], "entry_audits" => [],
        "idempotency_records" => [], "service_idempotency_receipts" => [] }
    end
    source = Timekeeping::Handoff::Checkpoint.build(tables: tables.call([entry.call(101, "a"), entry.call(202, "b")]))
    checkpoint = Timekeeping::Handoff::Checkpoint.build(
      tables: tables.call([entry.call(101, "changed a"), entry.call(202, "changed b")])
    )
    projection = [[101, "changed a"], [202, "changed b"]].map do |company_id, note|
      entry.call(company_id, note).merge("bill_status" => bill_number, "review_status" => review_number)
    end
    money = [101, 202].index_with { |company_id| { company_id:, values: {} } }
    result = described_class.run(
      source:, checkpoint:, projection:, source_intents: [], intents: [], next_entry_id: 1000,
      money_before: money, money_after: money
    )
    differences = result.companies.values.flat_map { |report| report.listed + report.unlisted }
    expect(differences.map(&:company_id)).to include(101, 202)

    stored = RailsEventViewer::Entry.where(name: "Timekeeping::ReconciliationDifferenceFound")
    expect { described_class.report(result) }.to change { stored.count }.by(differences.size)

    stored_company_ids = stored.order(:id).last(differences.size).map { |row| row.payload["data"]["company_id"] }
    expect(stored_company_ids).to match_array(differences.map(&:company_id))
    expect(JSON.generate(stored.map(&:payload))).not_to include("changed a")
  end
end

