      end
    end
  end
end

RSpec.describe Timekeeping::Handoff::Reconciliation do
  # "Reconciliation writes nothing and never repairs a difference"
  # A second run stands in for a resumed handoff: if the first run repaired the row in place, the second would pass.
  it "running twice over a projection difference issues no write and leaves the projection row unrepaired" do
    at = Time.utc(2026, 1, 5)
    bill_name, bill_number = TimesheetEntry.bill_statuses.first
    review_name, review_number = TimesheetEntry.review_statuses.first
    entry = {
      "id" => 7, "company_id" => 101, "version" => 1, "project_id" => 1, "user_id" => 1, "agent_id" => nil,
      "work_date" => Date.new(2026, 1, 5), "duration" => 60.0, "note" => "work", "bill_status" => bill_name,
      "review_status" => review_name, "locked" => false, "source" => "manual", "source_metadata" => {},
      "external_run_id" => nil, "external_session_id" => nil, "proof_url" => nil, "proof_metadata" => {},
      "discarded_at" => nil, "created_at" => at, "updated_at" => at
    }
    rows = { "entries" => [entry], "reservations" => [], "invoice_operations" => [], "entry_audits" => [],
             "idempotency_records" => [], "service_idempotency_receipts" => [] }
    projection = [entry.merge("bill_status" => bill_number, "review_status" => review_number, "version" => 0)]
    projection_before = Marshal.load(Marshal.dump(projection))
    money = { 101 => { company_id: 101, values: {} } }
    arguments = {
      source: Timekeeping::Handoff::Checkpoint.build(tables: rows),
      checkpoint: Timekeeping::Handoff::Checkpoint.build(tables: rows),
      projection:, source_intents: [], intents: [], next_entry_id: 1000, money_before: money, money_after: money
    }

    writes = []
    callback = lambda do |*, payload|
      writes << payload[:sql] if payload[:sql].match?(/\A\s*(INSERT|UPDATE|DELETE)/i)
    end
    first = second = nil
    ActiveSupport::Notifications.subscribed(callback, "sql.active_record") do
      first = described_class.run(**arguments)
      second = described_class.run(**arguments)
    end

    expect(writes).to be_empty
    expect(projection).to eq(projection_before)
    expect(first.companies.fetch(101).checks.fetch(:projection)).not_to be_empty
    expect(second.abort?).to be(true)
    expect(second.companies.fetch(101).unlisted).to eq(first.companies.fetch(101).unlisted)
  end
end
